import React, { useMemo } from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Typography,
  useMediaQuery,
  CircularProgress,
} from '@mui/material';
import { IMobileDataViewPayload } from '../../../core/Interface/mobile.interface';
import { useGetMobileInfoViewQuery } from '../../posApi';
import { theme } from '../../../theme';

interface MobileListDataProps {
  open: boolean;
  setOpen: (open: boolean) => void;
  requestCode: string;
}

const MobileViewListData: React.FC<MobileListDataProps> = ({
  open,
  setOpen,
  requestCode,
}) => {
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));

  const { data, isLoading } = useGetMobileInfoViewQuery(
    { requestCode },
    { skip: !requestCode }
  );

  const itemViewList = useMemo(() => {
    if (data?.data && Array.isArray(data.data) && data.data.length > 0) {
      return data.data[0] as IMobileDataViewPayload;
    }
    return null;
  }, [data?.data]);

  const handleClose = () => {
    setOpen(false);
  };

  return (
    <Dialog
      aria-labelledby="mobile-info-view"
      fullScreen={isMobile}
      fullWidth
      maxWidth="sm"
      onClose={handleClose}
      open={open}
    >
      {isLoading ? (
        <Box
          alignItems="center"
          display="flex"
          justifyContent="center"
          minHeight={200}
        >
          <CircularProgress />
        </Box>
      ) : (
        <>
          <DialogTitle
            id="mobile-info-view"
            sx={{
              fontWeight: 600,
              background: '#CFD8DC',
              borderRadius: 1,
              padding: '16px 24px',
            }}
          >
            Mobile Info View
          </DialogTitle>
          <DialogContent
            sx={{
              //display: 'grid',
              gridTemplateColumns: 'auto 10px auto',
              gap: 1,
              alignItems: 'center',
              padding: '10px 20px',
              mt: 2,
            }}
          >
            {itemViewList ? (
              <>
                
                <Typography
                  color="text.secondary"
                  variant="body1"
                >
                  <strong>{itemViewList.title}</strong>
                </Typography>

                <Typography
                  color="text.secondary"
                  variant="body1"
                >
                  {itemViewList.description}
                </Typography>

                {/* <Divider sx={{ my: 2 }} /> */}
                {itemViewList.items?.map((item, index) => (
                  <Box
                    key={index}
                    sx={{
                      display: 'flex',
                      justifyContent: 'space-between',
                      my: 1,
                    }}
                  >
                    <Typography variant="body2">{item.key}</Typography>
                    <Typography variant="body2">{item.value}</Typography>
                  </Box>
                ))}
              </>
            ) : (
              <Typography variant="body1">No data available</Typography>
            )}
          </DialogContent>
        </>
      )}
      <DialogActions sx={{ padding: '16px 24px' }}>
        <Button
          color="primary"
          onClick={handleClose}
          sx={{
            width: 200,
            height: 42,
            borderRadius: '5px',
            fontWeight: 'bold',
          }}
          variant="outlined"
        >
          Cancel
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default MobileViewListData;
