import { Box, BoxProps, Skeleton } from '@mui/material';
import React from 'react';

const TopInfoSkeleton = (props: BoxProps) => {
  return (
    <Box
      height={120}
      {...props}
    >
      <Skeleton
        height={120}
        sx={{ borderRadius: 1 }}
        variant="rectangular"
        width={'100%'}
      />
    </Box>
  );
};

export default React.memo(TopInfoSkeleton);
