import React from 'react';
import { Formik, Form, Field, FieldProps } from 'formik';
import SearchIcon from '@mui/icons-material/Search';
import { TextField, InputAdornment, Button, Box, Grid } from '@mui/material';
import { appColors } from '../../theme/appColors';
import { useTranslation } from 'react-i18next';

interface ISearchForm {
  setSearchText: (searchText: string) => void;
}

const SearchForm: React.FC<ISearchForm> = ({ setSearchText }) => {
  const { t } = useTranslation(['common']);

  return (
    <Formik
      initialValues={{ searchText: '' }}
      onSubmit={(values) => {
        setSearchText(values.searchText);
      }}
    >
      <Form>
        <Field name="searchText">
          {({ field }: FieldProps<string>) => (
            <Box sx={{ py: 2 }}>
              <Grid
                container
                display="flex"
                flexDirection="row"
                item
                justifyContent="flex-end"
                key={3}
              >
                <TextField
                  {...field}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <SearchIcon />
                      </InputAdornment>
                    ),
                  }}
                  placeholder="Search..."
                  size="small"
                  sx={{
                    mr: 2,
                    mb: 0,
                    marginTop: '20px',
                    '& .MuiFormLabel-root.MuiInputLabel-root': {
                      color: appColors.darkGray[20],
                    },
                    width: 300,
                  }}
                  type="text"
                  variant="outlined"
                />
                <Button
                  sx={{
                    mb: 0,
                    border: 'none',
                    backgroundColor: appColors.darkGreen[20],
                    marginTop: '20px',
                    borderRadius: '8px',
                    cursor: 'pointer',
                    width: 120,
                    height: 42,
                    fontWeight: 'bold',
                    '&:hover': {
                      backgroundColor: appColors.greyishBlue[20],
                    },
                  }}
                  type="submit"
                  variant="outlined"
                >
                  {t('common:search')}
                </Button>
              </Grid>
            </Box>
          )}
        </Field>
      </Form>
    </Formik>
  );
};

export default SearchForm;
