import React, { useMemo, useState } from 'react';
import {
  Card,
  CardContent,
  Typography,
  Divider,
  IconButton,
  Box,
  Grid,
} from '@mui/material';
import { useTranslation } from 'react-i18next';
import { useGetMobileInfoQuery } from '../posApi';
import TopInfoSkeleton from '../Dashboard/TopInfoSkeleton';
import { IMobileData } from '../../core/Interface/mobile.interface';
import ArrowForwardIosIcon from '@mui/icons-material/ArrowForwardIos';
import AnimatedPage from '../../layouts/AnimatedPage';
import SearchForm from '../../components/ModelPopup/SearchForm';
import MobileViewListData from './components/mobileInfoView';

const MobileInfo = () => {
  const { t } = useTranslation(['common']);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedRequestCode, setSelectedRequestCode] = useState<string | null>(
    null
  );
  const [openDialog, setOpenDialog] = useState(false);

  const { data, isLoading } = useGetMobileInfoQuery({
    pageIndex: 0,
    pageSize: 50,
    searchText: '',
  });

  const itemList = useMemo(() => {
    return data?.data as IMobileData[];
  }, [data?.data]);

  const handleSearch = (text: string) => {
    setSearchQuery(text);
  };

  const filteredItemList = useMemo(() => {
    const query = searchQuery.toLowerCase().trim();
    return itemList?.filter((re) => {
      const itemTitle = re.title.toLowerCase();
      return itemTitle.includes(query);
    });
  }, [itemList, searchQuery]);

  const handleOpenDialog = (requestCode: string) => {
    setSelectedRequestCode(requestCode);
    setOpenDialog(true);
  };

  return (
    <AnimatedPage>
      <Box data-testid="mobile-info">
        <Box sx={{ py: 2 }}>
          <Grid
            container
            justifyContent="flex-end"
          >
            <SearchForm setSearchText={handleSearch} />
          </Grid>
        </Box>

        <Grid
          container
          spacing={4}
        >
          {!isLoading &&
            filteredItemList.map((value, index) => (
              <Grid
                item
                key={index}
                lg={3}
                md={6}
                sm={12}
                xs={12}
              >
                <Card
                  sx={{ position: 'relative', overflow: 'visible' }}
                  variant="outlined"
                >
                  <CardContent>
                    <Typography
                      component="div"
                      fontWeight="bold"
                      variant="h6"
                    >
                      {value.title}
                    </Typography>
                    <Typography
                      sx={{ opacity: 0.8 }}
                      variant="subtitle2"
                    >
                      {value.description}
                    </Typography>
                    <Divider
                      flexItem
                      sx={{ my: 2 }}
                    />
                    {value.items.map((item, itemIndex) => (
                      <Box
                        key={itemIndex}
                        sx={{
                          display: 'flex',
                          justifyContent: 'space-between',
                          mt: itemIndex === 0 ? 0 : 1,
                        }}
                      >
                        <Typography variant="body2">{item.key}</Typography>
                        <Typography variant="body2">{item.value}</Typography>
                      </Box>
                    ))}
                  </CardContent>
                  <IconButton
                    onClick={() => handleOpenDialog(value.requestCode)}
                    sx={{ position: 'absolute', top: '16px', right: '16px' }}
                  >
                    <ArrowForwardIosIcon />
                  </IconButton>
                </Card>
              </Grid>
            ))}

          {isLoading &&
            [1, 2, 3, 4].map((i) => (
              <Grid
                item
                key={i}
                md={4}
                xs={12}
              >
                <TopInfoSkeleton />
              </Grid>
            ))}

          {!isLoading && itemList.length === 0 && (
            <Typography
              align="center"
              width="100%"
            >
              {t('common:noData')}
            </Typography>
          )}
        </Grid>

        <MobileViewListData
          open={openDialog}
          requestCode={selectedRequestCode || ''}
          setOpen={setOpenDialog}
        />
      </Box>
    </AnimatedPage>
  );
};

export default MobileInfo;
